(function () {
    var countryListContainer = $('.country-list-container');
    if (countryListContainer.length === 0) {
        return;
    }
    var mode = $('#countrylistMode').val();
    var regionKeys = _.keys(JSON.parse($('#countryList').val()));
    var newCountryListValues = _.values(JSON.parse($('#countryList').val()));
    var customCountryList = JSON.parse($('#customCountryList').val());
    var newList = [];
    if (mode == 'automatic') {
        _.map(newCountryListValues, function (value, index) {
            newList.push({list: []});
            _.map(value, function (val, ind) {
                newList[index].title = regionKeys[index];
                newList[index].list[ind] = val;
            });
        });
    } else {
        _.forEach(customCountryList, (item) => {
            var obj = {
                title: item.regionName,
                list: item.regionList
            }
            newList.push(obj);
        });
    }

    var countryListVM = {
        countryList: ko.observable(newList),
        clickToCollapse: function (index, data, event) {
            var context = ko.contextFor(event.target);
            var _index = context.$index(), list = $('.list');
            $(list[_index]).toggleClass('active');
        }
    };
    ko.applyBindings(countryListVM, countryListContainer.get(0));
})();

(function () {
	var carouselComp = $('.header-carousel-container');
	if (carouselComp.length === 0) {
		return;
	}
	var carouselCompSwipe = [];
	var carouselItemSize = $('#carouselItemSize').val();
	var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');

	function getTrackingDate(swiper) {
			itemName = swiper.activeIndex;
			
			var viewTrackData = {
					event_name: "view_promotion",
					event_parameters: {
							promotion_name: "banner_" + itemName,
							module_name: "TopBanner",
					}
			}
			return viewTrackData;
	}

	/**
	 * 判断元素是否进入视口
	 * @param {*} el 
	 * @returns 
	 */

	function isElementVisible(el) {
			var rect = el.getBoundingClientRect()
			var vWidth = window.innerWidth || document.documentElement.clientWidth
			var vHeight = window.innerHeight || document.documentElement.clientHeight
			if (
					rect.right < 0 ||
					rect.bottom < 0 ||
					rect.left > vWidth ||
					rect.top > vHeight
			) {
					return false
			}
			return true
	}

	$.each(carouselComp, function (index, carouselCompItem) {
		var swiperSlides = $(carouselCompItem).find('.swiper-slide');
		var trackElementContainer = $(carouselCompItem).find('.track-view-element-container');
		var swiperContainerTarget = $(carouselCompItem).find('.swiper');
		var swiperWrapper = $(carouselComp).find('.swiper-wrapper');
		swiperContainerTarget.addClass('header-carousel-swiper' + index);
		swiperContainerTarget.attr('data-index', index);
		var afterTrackingViewEle = [];
		swiperSlides.length > 1
			? (carouselCompSwipe[index] = new Swiper('.header-carousel-swiper' + index, {
				slidesPerView: 1,
				slidesPerGroup: 1,
				spaceBetween: 16,
				dotLimit: 5,
				loop: true,
				effect: 'fade',
				threshold: 10,
				autoplay:
					carouselItemSize > 1
						? {
							delay: 5000,
							disableOnInteraction: false,
						}
						: false,
				pagination: {
					el: '.swiper-pagination',
					clickable: true,
					renderBullet: function (index, className) {
						return '<span class="' + className + '" data-offsetx="+"index"+"></span>';
					},
				},
				on: {
					paginationRender: function () {
						this.translateValue = 0;
						renderCustomBullets(this.$el, this.params.dotLimit);
					},
					slideChange: function () {
						setCustomPageBullets(this, this.params.dotLimit);
					},
					realIndexChange: function(swiper){
						var realIndex = swiper.realIndex;
						if(isElementVisible(swiper.el) && afterTrackingViewEle.indexOf(realIndex.toString()) <= -1) {
							afterTrackingViewEle.push(realIndex.toString());
							var viewTrackData = JSON.parse($(swiper.slides[swiper.activeIndex]).attr('data-view-track'));
							trackingSiperSlide.swiper = swiper.slides[realIndex];
							trackingSiperSlide.viewTrackData = viewTrackData;
							window.dispatchEvent(trackingSiperSlide);
						}
					}
				},
			}))
			: swiperWrapper.addClass('no-swiper');

			if(trackElementContainer.length > 0) {
				var intersectionObserver = new IntersectionObserver(function(entries) {
					entries.forEach(function(entry) {
						if (entry.isIntersecting && entry.intersectionRatio > 0) {
							var target = entry.target;
							var activeEle = $(target).find('.swiper-slide');
							var activeIndex = '0';
							if(activeEle.length > 1){
								activeEle = $(target).find('.swiper-slide-active');
								activeIndex = activeEle.attr('data-swiper-slide-index');
							}
							if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
								afterTrackingViewEle.push(activeIndex);
								var viewData = JSON.parse(activeEle.attr('data-view-track'));
								trackingSiperSlide.swiper = target;
								trackingSiperSlide.viewTrackData = viewData;
								window.dispatchEvent(trackingSiperSlide);
							}
						
						}
					});
				});
				intersectionObserver.observe(trackElementContainer[0]);
			}
	});
})();

(function () {
	var homeCarousel = $('.home-carousel-container');
	if (homeCarousel.length === 0) {
		return;
	}
	var carousels = [];
	var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');

	/**
	 * 自定义Pagination下标指示器
	 * @param swiper 轮播对象
	 * @param current 当前幻灯片
	 * @param total 总的幻灯片数量
	 * @param showTitle 是否显示小标题
	 * @returns {*} 格式化后的HTML内容
	 */
	function renderPagination(swiper, current, total, showTitle) {
		if (total <= 1) return;
		if (swiper.asyncProgress) clearInterval(swiper.asyncProgress);

		var pagination = $(swiper.$el).find('.swiper-pagination').get(0);
		var currentSlide = $(swiper.$el).find('.swiper-wrapper .swiper-slide').get(current);
		var slideTitle = currentSlide.getAttribute('data-slide-title');
		var theme = currentSlide.getAttribute('data-theme');
		var autoplay = $(swiper.$el).data('autoplay');

		$(pagination).removeClass('theme-black theme-default').addClass(theme);

		// Elements
		var paginationWrapper = $('<div class="my-bullet-pagination-wrapper"></div>');
		var bullet = $('<div class="my-bullet-pagination"></div>');
		var title = $('<span class="my-bullet-pagination-title"></span>').html(slideTitle);
		var dotsWrapper = $('<div class="my-bullet-pagination-dots-wrapper"></div>');
		var toggleButton = $('<span class="toggle-display"><i class="icon-control"></i></span>').attr('data-status', 'play');

		for (var i = 0; i < total; i++) {
			var dot = $(
				'<div class="my-bullet-pagination-dots"><div class="my-bullet-pagination-dots-icon"><div class="my-bullet-pagination-dots-process outer"></div><div class="my-bullet-pagination-dots-process inner"></div></div></div>'
			);
			if (current === i + 1) {
				dot.addClass('active');
			}
			dotsWrapper.append(dot);
		}

		if (autoplay) dotsWrapper.append(toggleButton);

		dotsWrapper.css('width', 138 + (total - 1) * 20 + 'px');

		if (showTitle) bullet.append(title).addClass('displayTitle');
		bullet.append(dotsWrapper);

		paginationWrapper.append(bullet);

		setTimeout(function () {
			renderProcessBar(swiper);

			// Events
			var paginationDots = $(pagination).find('.my-bullet-pagination-dots');
			paginationDots.on('click', function () {
				var index = $(this).index();
				swiper.slideToLoop(index);
			});
			var togglePlay = $($(swiper.$el).find('.toggle-display').get(0));
			togglePlay.on('click', function () {
				var status = $(this).get(0).dataset.status;
				switch (status) {
					case 'play':
						togglePlay.attr('data-status', 'suspend');
						swiper.autoplay.stop();
						swiper.reset();
						break;
					case 'suspend':
						togglePlay.attr('data-status', 'play');
						swiper.autoplay.start();
						break;
				}
			});
		}, 0);

		return paginationWrapper.prop('outerHTML');
	}

	/**
	 * 加载进度条
	 * @param swiper 轮播对象
	 */
	function renderProcessBar(swiper) {
		var dotEl = $(swiper.$el).find('.my-bullet-pagination-dots.active .my-bullet-pagination-dots-icon');
		var dotOuter = $(swiper.$el).find('.my-bullet-pagination-dots.active .outer');
		var dotInner = $(swiper.$el).find('.my-bullet-pagination-dots.active .inner');
		var autoplay = $(swiper.$el).data('autoplay');
		dotEl.css({ width: '80px', 'background-color': 'transparent' });
		dotOuter.css({ width: '80px' });
		if (!autoplay) {
			dotInner.css({ width: '80px', 'transition-duration': '300ms' });
			return;
		}
		var delay = $(swiper.$el).data('autoplay-delay');
		var index = 1;
		var total = (delay * 1000 - 800) / 25;
		swiper.asyncProgress = setInterval(function () {
			var status = $(swiper.$el).find('.toggle-display').get(0).dataset.status;
			if (index < total && status === 'play') {
				dotInner.css({ width: (index / total) * 80 + 'px', 'transition-duration': '0ms' });
				index++;
			}
		}, 25);
		swiper.reset = function () {
			index = 1;
			dotInner.css({ width: '1px', 'transition-duration': '300ms' });
		};
	}

		/**
		 * 获取view Tracking的数据
		 */
		function getTrackingDate(el) {
				var activeSlide = el.slides[el.activeIndex];
				var title = $(activeSlide).find('.swiper-product-introduction-title');
				title = title.length > 0? title[0].innerHTML.replace(/<[^>]+>/g, ''): ("banner_" + el.realIndex);
				var viewTrackData = {
						"event_name":"view_promotion", 
						"event_parameters":{
								"module_name":"TopBanner",
								"promotion_name": title,
								"promotion_id": el.realIndex.toString()
						}
				}
				return viewTrackData;
		}
		/**
		 * 判断元素是否进入视口
		 * @param {*} el 
		 * @returns 
		 */

		function isElementVisible(el) {
				var rect = el.getBoundingClientRect()
				var vWidth = window.innerWidth || document.documentElement.clientWidth
				var vHeight = window.innerHeight || document.documentElement.clientHeight
				if (
						rect.right < 0 ||
						rect.bottom < 0 ||
						rect.left > vWidth ||
						rect.top > vHeight
				) {
						return false
				}
				return true
		}

	/**
	 * 初始化Swiper
	 */
	function createSwiperObjects() {
		$.each(homeCarousel, function (index, homeCarouselItem) {
			var afterTrackingViewEle = [];
			// Get Container, Wrapper, Slides
			var container = $(homeCarouselItem).find('.swiper');
			var trackElementContainer = $(homeCarouselItem).find('.track-view-element-container');
			var wrapper = $(homeCarouselItem).find('.swiper-wrapper');
			var slides = $(homeCarouselItem).find('.swiper-slide.swiper-original');
			var prevEl = container.find('.pagination-left');
			var nextEl = container.find('.pagination-right');
			// Tag element
			container.addClass('home-carousel-swiper' + index).data('index', index);
			// Check the children length
			if (slides.length <= 1) {
				wrapper.addClass('no-swiper');
				prevEl.addClass('no-pagination');
				nextEl.addClass('no-pagination');
				getCountdownDisplay(slides, 0);
				var title = wrapper.find('.swiper-product-introduction-title');
				title = title.length > 0? title[0].innerHTML.replace(/<[^>]+>/g, ''): ("banner_0");
				var viewTrackData = {
						"event_name":"view_promotion", 
						"event_parameters":{
								"module_name":"TopBanner",
								"promotion_name": title,
								"promotion_id": "0"
						}
				};
				wrapper.parent().attr("data-view-track", JSON.stringify(viewTrackData));

				var observe = new IntersectionObserver(function(entry) {
						if (entry[0].isIntersecting && entry[0].intersectionRatio > 0) {
								var target = entry[0].target;
								var viewData = JSON.parse(target.getAttribute('data-view-track'));
								trackingSiperSlide.viewTrackData = viewData;
								window.dispatchEvent(trackingSiperSlide);
								observe.unobserve(target);
						}
				});
				observe.observe(trackElementContainer[0]);
				return;
			}
			// Get config of Slides
			var autoplay = container.data('autoplay');
			var delay = container.data('autoplay-delay');
			var showSlideTitle = container.data('show-slidetitle');
			var swiper = new Swiper('.home-carousel-swiper' + index, {
				observer: true,
				observeParents: true,	//监测Swiper 的祖/父元素
				speed: 1000,
				threshold: 10,
				touchStartForcePreventDefault: true, // 当配置slide为视频时，同时点击视频本身可以跳转链接，拖放滑动swiper时会失效，需要强制对touchstart事件preventDefault
				loop: true,
				autoplay: autoplay
					? {
							delay: delay * 1000 - 800,
							stopOnLastSlide: false,
							disableOnInteraction: false,
						}
					: false,
				longSwipesRatio: 0.2,
				effect: 'fade',
				fadeEffect: {
					crossFade: true,
				},
				isClick: false, // 是否点击标识符，区分mouseenter和click事件
				// 显示分页
				pagination: {
					el: '.swiper-pagination',
					clickable: true, //允许分页点击跳转
					// 自定义分页器
					type: 'custom',
					renderCustom: function (swiper, current, total) {
						return renderPagination(swiper, current, total, showSlideTitle);
					},
				},
				navigation: {
					nextEl: ".pagination-right",
					prevEl: ".pagination-left",
				},
				on: {
					init: function(swiper) {
							var viewTrackData =	getTrackingDate(swiper);
							swiper.el.setAttribute('data-view-track', JSON.stringify(viewTrackData));
							var swiperSlides = swiper.slides;
							for(var i = 0; i < swiperSlides.length; i++) {
									(function(i) {
											getCountdownDisplay(swiperSlides, i, swiper);
									})(i);
							}
					},
					realIndexChange: function(swiper){
							var viewTrackData = getTrackingDate(swiper);
							swiper.el.setAttribute('data-view-track', JSON.stringify(viewTrackData));
							if(isElementVisible(swiper.el) && afterTrackingViewEle.indexOf(swiper.realIndex.toString()) <= -1){
									afterTrackingViewEle.push(swiper.realIndex.toString());
									trackingSiperSlide.swiper = swiper.slides[swiper.activeIndex];
									trackingSiperSlide.viewTrackData = viewTrackData;
									window.dispatchEvent(trackingSiperSlide);
							}
					},
					slideChange: function(swiper) {
						// 当前slide的视频从头播放
						var currentSlide = $(swiper.slides[swiper.activeIndex]);
						var currentVideo = currentSlide.find('.video-type-container video');
						if(currentVideo.length > 0) {
							var video = currentVideo.get(0);
							if(video) {
								video.currentTime = 0;
							}
						}
						var currentClip = currentSlide.find('.video-type-container canvas');
						if(currentClip.length > 0) {
							var canvas = currentClip.get(0);
							if(canvas && canvas.player) {
								canvas.player.currentTime = 0;
							}
						}
					}
				},
			});
			carousels.push(swiper);
			if(trackElementContainer.length > 0) {
					var intersectionObserver = new IntersectionObserver(function(entries) {
							entries.forEach(function(entry) {
									if (entry.isIntersecting && entry.intersectionRatio > 0) {
											var target = entry.target;
											var activeELe = $(target).find('.swiper-slide-active');
											var activeIndex = activeELe.attr('data-swiper-slide-index');
											if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
													afterTrackingViewEle.push(activeIndex);
													var viewData = JSON.parse(target.getAttribute('data-view-track'));
													trackingSiperSlide.swiper = target;
													trackingSiperSlide.viewTrackData = viewData;
													window.dispatchEvent(trackingSiperSlide);
											}
											
									}
							});
					});
					intersectionObserver.observe(trackElementContainer[0]);
			}
		});
	}

	function getAxiosTime() {
			var url = "https://www.tcl.com/tcl-vue-h5/time";
			return axios.get(url).then(function(res) {
					return res.data
			})
	}

	function changeNumber(oLis, len, secDiffTimes, slideItem, endStatus, swiper) {
			var diffStrTime = getStrTime(secDiffTimes);
			var boxHeight = $(oLis[0]).find('.number-item')[0].getBoundingClientRect().height / 10;
			for (var i = 0; i < len; i++) {
					if (i == 2 || i == 5 || i == 8) {
							continue;
					}
					var itemLength = $($(oLis[i]).find('.number-item')[0]).find('.tcl-icon').length;
					var numberIndex = $($(oLis[i]).find('.number-item')[0]).find('.tcl-icon.icon-b-' + diffStrTime.charAt(i)).index();
					if(numberIndex == 0) {
							var currentMarginTop = $(oLis[i]).find(".number-item").eq(0).css('marginTop');
							if (currentMarginTop != '0px') {
									$(oLis[i]).find(".number-item").eq(0).stop().animate({
											marginTop: -(boxHeight * itemLength)
									}, 300, function() {
											$(this).css('marginTop', '0px');
									});
							}
					} else {
							$(oLis[i]).find(".number-item").eq(0).stop().animate({
									marginTop: -(boxHeight * numberIndex)
							}, 300)
					}
			}
			if (secDiffTimes > 0) {
					secDiffTimes--;
					setTimeout(function () { changeNumber(oLis, len, secDiffTimes, slideItem, endStatus, swiper) }, 1000);
			} else {
					afterSecondGetZero(endStatus, slideItem, swiper);
			}
	}
	function afterSecondGetZero(endStatus, slideItem, swiper) {
			switch (endStatus) {
					case 'hideBar':
							$(slideItem).find('.countdown-container').css('display', 'none');
							$(slideItem).find('.swiper-product-introduction.after-timer-result').removeClass('after-timer-result');
							break;
					case 'showOther':
							var showCountIndex = $(slideItem).attr('data-countdown-index');
							if (showCountIndex) {
									var newSlide = $($(slideItem).parents('.home-carousel-container').find('.count-down-container .swiper-slide').eq(showCountIndex)[0]).clone(true);
									if(newSlide.length > 0) {
											newSlide.addClass('swiper-original');
											$(slideItem).css('transition', 'opacity 0.7s ease-in-out').addClass('hide-slide-ele').fadeOut(700, function() {
													$(this).replaceWith(newSlide);
													setTimeout(function() {
															newSlide.removeClass('hide-slide-ele');
															window.lazyLoad();
													}, 0);
											});
											if(swiper) {
													setTimeout(function() {
															if(slideItem.classList.contains('swiper-slide-active')) {
																	var newSlideTitle = $(newSlide).attr('data-slide-title');
																	var newTheme = $(newSlide).attr('data-theme');
																	var hasPagination = swiper.$el.find('.swiper-pagination');
																	if(hasPagination.length > 0) {
																			hasPagination.removeClass("theme-black theme-default").addClass(newTheme);
																			$(hasPagination).find('.my-bullet-pagination-title').html(newSlideTitle);
																	}
															}
															swiper.update();
													}, 100)
											}
									}
							}
			}
	}

	function getStrTime(secDiffTimes) {
			var days = getTwoStr(Math.floor(secDiffTimes / (24 * 60 * 60)));
			var hours = getTwoStr(Math.floor(secDiffTimes / (60 * 60)) - (days * 24));
			var minutes = getTwoStr(Math.floor(secDiffTimes / 60) - (days * 24 * 60) - (hours * 60));
			var seconds = getTwoStr(Math.floor(secDiffTimes) - (days * 24 * 60 * 60) - (hours * 60 * 60) - (minutes * 60));
			return days + ":" + hours + ":" + minutes + ":" + seconds;
	}

	function getTwoStr(a) {
			var num = a < 0 ? "00" : (a < 10 ? "0" + a : "" + a);
			return num;
	}

	function getCountdownDisplay(swiperSlides, i, swiper) {
			var slideItem = swiperSlides[i];
			var hasProductContainer = $(slideItem).find('.swiper-product-introduction');
			var hasTimeCount;
			var hasContent = hasProductContainer.get(0);
			if(hasContent) {
					hasTimeCount = hasContent.classList.contains('after-timer-result');
			}
			var timestamp = slideItem.getAttribute('data-timestamp');
			var rediType = slideItem.getAttribute('data-redirect-type');
			if(rediType && rediType === 'countdownType' && timestamp && timestamp !== '') {
					getAxiosTime().then(function (timeData) {
							timeData = timeData.replace('/', ' ').replace('/', ',').replace(':', ' ');
							var systemTimestamp = new Date(timeData).getTime();
							var diffTimes = timestamp - systemTimestamp; //时间差值；
							var endStatus = slideItem.getAttribute('data-end-status');
							var secDiffTimes = diffTimes / 1000;
							if (secDiffTimes >= 1) {
									var oLis = $(slideItem).find('.swiper-number');
									var len = oLis.length;
									if(secDiffTimes > 8639999) {
											secDiffTimes = 8639999;
									}
									if(hasTimeCount) {
											hasProductContainer.removeClass('after-timer-result')
									}
									changeNumber(oLis, len, secDiffTimes, slideItem, endStatus, swiper);
							} else {
									afterSecondGetZero(endStatus, slideItem, swiper)
							}
					})
			}
	}
	createSwiperObjects();
})();

(function () {
	var keyBannerSimpleVideo = $('.key-banner-simple-video');
	if (keyBannerSimpleVideo.length == 0) {
		return;
	}
	var videoList = [];
	var screenHeight = window.innerHeight || document.documentElement.clientHeight;
	var desktop = (window.innerWidth || document.documentElement.clientWidth) > 1279;

	_.forEach(keyBannerSimpleVideo, function (videoEl) {
		if (desktop) {
			var offsetTop = $(videoEl).offset().top;
			var scrollTop=$(window).scrollTop();
			if (offsetTop >= scrollTop && offsetTop < scrollTop+screenHeight||offsetTop<screenHeight&&scrollTop>0) {
				videoEl.play();
				$(videoEl).attr('autoplay', 'true');
				$(videoEl).attr('loop', 'true');
			} else {
				videoList.push({ el: videoEl, height: $(videoEl).offset().top });
			}
		}
	});
	$(window).scroll(function () {
		if (desktop&&videoList.length>0) {
			videoList.map(function (video) {
				var offsetY = $(window).scrollTop();
				if (video.el.paused && video.height >= offsetY && video.height < offsetY+screenHeight) {
					video.el.play();
					$(video.el).attr('autoplay', 'true');
					$(video.el).attr('loop', 'true');
				}
			});
		}
	});
})();

(function () {
	var featureTabComponents = $('.key-feature-tab-container');
	if (featureTabComponents.length === 0) {
		return;
	}
	var tabWidth = $('.key-feature-tab-container').width(); // 容器宽度

	var tabSlides = $('.key-feature-tab-container .swiper-slide');
	var keyFeatureSwiper = [];
	var deviceType = window.screenInfo.scope;
	var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');
	/**
	 * 切换标签
	 */
	function toggleTab(target, index) {
		target.addClass('active');
		target.parents('.tab-list').scrollLeft(target.offset().left);
		$.each(target.siblings(), function (i, tabEl) {
			$(tabEl).removeClass('active');
		});
		var currentTabSlides = target.parents('.key-feature-tab').find('.swiper-slide');
		var currentTheme = currentTabSlides.get(index).dataset.theme;
		var headerWrap = target.parents('.key-feature-tab').find('.header-wrap');
		var textWrap = target.parents('.key-feature-tab').find('.text-wrap');
		var ctaWrap = target.parents('.key-feature-tab').find('.cta-wrap');
		headerWrap.removeClass('black white').addClass(currentTheme);
		textWrap.removeClass('black white').addClass(currentTheme);
		ctaWrap.removeClass('black white').addClass(currentTheme);
	}

	/**
	 * 计算视窗尺寸
	 */
	function calculateWindowSize() {
		deviceType = window.screenInfo.scope;
		tabWidth = $('.key-feature-tab-container').width();
		// 初始化宽度
		tabSlides.each(function (index, tab) {
			$(tab).css({
				width: tabWidth + 'px',
			});
		});
	}

	/**
	 * 标签点击
	 */
	$('.key-feature-tab-container .tab-item').on('click', function (event) {
		var index = this.dataset.index;
		var tarSwiperIndex = $(this).parent().parent().parent().parent().find('.swiper').attr('data-index');
		keyFeatureSwiper[tarSwiperIndex].slideTo(index, 1000, false);
	});

	/**
	 * 初始化
	 */
	function init() {
		// 设置主题
		$.each(featureTabComponents, function (index, tabComp) {
			var slides = $(tabComp).find('.swiper-slide');
			var theme = slides.get(0).dataset.theme;
			var swiperContainerTarget = $(tabComp).find('.swiper');
			swiperContainerTarget.addClass('key-container-swiper' + index);
			swiperContainerTarget.attr('data-index', index);
			var trackElementContainer = $(tabComp).find('.track-view-element-container');
			var afterTrackingViewEle = [];
			slides.length > 1 &&
				(keyFeatureSwiper[index] = new Swiper('.key-container-swiper' + index, {
					autoplay: false, //可选选项，自动滑动
					preventClicks: true,
					threshold: deviceType === 'desktop' ? 100 : false,
					on: {
						slideChange: function (event) {
							var targetSwipe = $(event.$el);
							var eventDom = targetSwipe.parent().find('.tab-item').eq(this.activeIndex);
							if (eventDom.length) {
								toggleTab(eventDom, this.activeIndex);
							}
						},
						resize: function () {
							calculateWindowSize();
						},
						transitionEnd: function(event) {
								var activeIndex = event.activeIndex.toString();
								if(afterTrackingViewEle.indexOf(activeIndex) <= -1){
										afterTrackingViewEle.push(activeIndex);
										var viewTrackData = JSON.parse($(event.slides[event.realIndex]).attr('data-view-track'));
										trackingSiperSlide.swiper = event.slides[event.activeIndex];
										trackingSiperSlide.viewTrackData = viewTrackData;
										window.dispatchEvent(trackingSiperSlide);
								}
						}
					},
				}));
			$(tabComp).find('.header-wrap').removeClass('black white').addClass(theme);
			$(tabComp).find('.text-wrap').removeClass('black white').addClass(theme);
			$(tabComp).find('.cta-wrap').removeClass('black white').addClass(theme);

			if(trackElementContainer.length > 0) {
					var intersectionObserver = new IntersectionObserver(function(entries) {
							entries.forEach(function(entry) {
									if (entry.isIntersecting && entry.intersectionRatio > 0) {
											var target = entry.target;
											var sctiveEle = $(target).find('.swiper-slide-active');
											var activeIndex = sctiveEle.attr('data-slide-index');
											if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
													afterTrackingViewEle.push(activeIndex);
													var viewData = JSON.parse(sctiveEle.attr('data-view-track'));
													trackingSiperSlide.swiper = target;
													trackingSiperSlide.viewTrackData = viewData;
													window.dispatchEvent(trackingSiperSlide);
											}
											
									}
							});
					});
					intersectionObserver.observe(trackElementContainer[0]);
			}
		});
	}

	init();
})();

