    if (cmpLayoutContainer.length > 0) {
        cmpLayoutContainer.addClass('full-container');
    }
    var tpl = function (htmlStr) {
        return htmlStr.split(/\$\{(.+?)\}/g);
    };
    var render = function (props) {
        return function (tok, i) {
            return i % 2 ? props[tok] : tok;
        };
    };
    // 最大页码
    // pc固定10, mobile根据屏幕计算
    var MAX_PAGE_DEFAULT = 10;
    var maxPage = MAX_PAGE_DEFAULT;
    maxPage = calculateMaxPage();

    // $(window).resize(
