    /**
     * 根据不同的列布局获取Swiper配置
     * @param columns 行列值
     * @returns {*}
     */
    function getBreakpointsByColumns(columns) {
        var map = {
            2: {
                320: {
                    slidesPerGroup: 1,
                },
                535: {
                    slidesPerView: 'auto',
                    slidesPerGroup: 2,
                },
                792: {
                    slidesPerView: 2,
                    slidesPerGroup: 2,
                },
                835: {
                    slidesPerView: 2,
                    slidesPerGroup: 2,
                },
                1200: {
                    slidesPerGroup: 2,
                },
            },
            3: {
                320: {
                    slidesPerGroup: 1,
                },
                535: {
                    slidesPerGroup: 2,
                },
                792: {
                    slidesPerView: 3,
                    slidesPerGroup: 3,
                },
                835: {
                    slidesPerView: 3,
                    slidesPerGroup: 3,
                },
                1200: {
                    slidesPerGroup: 3,
                },
            },
            4: {
                320: {
                    slidesPerGroup: 1,
                },
                535: {
                    slidesPerView: 'auto',
                    slidesPerGroup: 2,
                },
                835: {
                    slidesPerView: 4,
                    slidesPerGroup: 4,
                },
                1200: {
                    slidesPerGroup: 4,
                },
            },
        };
        return map[String(columns)];
    }

    /**
     * 生成信息卡片
     * @param data 卡片数据
     * @returns {*} html string
     */
    function generatorMessageCard(data, dataHeading, thumbnailRatio) {
        var listitem = $('<div class="list-item"></div>');
        var container = $(
            tpl('<div class="message-card-item"></div>').map(render(data)).join('')
        );
        var thumbnail = $(
            tpl(
                '<a class="thumbnail" style="padding-top: ' + thumbnailRatio + '%"><div class="background"><img src="${picture}" alt="${title}"/></div></a>'
            )
                .map(render(data))
                .join('')
        );
        var content = $('<section class="message-card-content"></section>');
        var mainContent = $('<div class="main-content"></div>');
        var title = $('<a></a>');
        var description = $(tpl('<p class="message-card-description">${description}</p><').map(render(data)).join(''));
        var mark = $(tpl('<p class="message-card-mark">${mark}</p>').map(render(data)).join(''));
        var button = $(
            tpl(
                '<a class="button-link"><span class="button-text">${buttonText}</span><i class="tcl-icon icon-Linear_Right"></i></a>'
            )
                .map(render(data))
                .join('')
        );
        var tags = $(
            '<div class="tags">' +
            $.map(data.tagItems, function (tag, i) {
                return '<span class="tag">' + tag.title + '</span>';
            }).join('') +
            '</div>'
        );
        if (data.title) mainContent.append(title);
        if (data.description) mainContent.append(description);
        if (data.mark) mainContent.append(mark);
        if (data.title || data.description || data.mark)
            content
                .append(mainContent)
                .addClass(data.picture ? 'with-thumbnail' : 'without-thumbnail')
                .addClass('align-' + data.align);
        title.addClass(data.redirect ? "with-redirect" : "without-redirect");
        title.append($('<' + dataHeading + ' class="message-card-title">' + data.title + '</' + dataHeading + '>'));
        if (data.redirect) title.attr('href', data.redirect);
        if (data.target) title.attr('target', data.target);
        if (data.nofollow) title.attr('rel', 'nofollow');
        if (data.messageCarouselClickTrackEvent) title.attr('data-click-track', data.messageCarouselClickTrackEvent);
        if (data.buttonText) content.append(button);
        if (data.tagItems && data.tagItems.length > 0) content.append(tags);
        if (data.picture) container.append(thumbnail);

        if (data.buttonLink) button.attr('href', data.buttonLink);
        if (data.buttonTarget) button.attr('target', data.buttonTarget);
        else if (data.target) button.attr('target', data.target);
        if (data.buttonNofollow) button.attr('rel', 'nofollow');

        thumbnail.addClass(data.redirect || data.useVideo ? "with-redirect" : "without-redirect")
        if (data.useVideo) {
            thumbnail.attr('data-use-video', true);
            thumbnail.attr('data-video-type', data.videoType);
            thumbnail.attr('data-video-src', data.video);
            thumbnail.append($('<i class="icon-play"></i>'));
        } else {
            if (data.redirect) thumbnail.attr('href', data.redirect);
            if (data.target) thumbnail.attr('target', data.target);
            if (data.nofollow) thumbnail.attr('rel', 'nofollow');
            if (data.messageCarouselClickTrackEvent) thumbnail.attr('data-click-track', data.messageCarouselClickTrackEvent);
        }
        container.append(content);
        listitem.append(container);

        return listitem.prop('outerHTML');
    }

    /**
     * 获取视频进度信息
     */
    function videoPlayTrack(event, videoTitle) {
        var _this = event;
        var videoUrl = _this.currentSrc();
        var fileName = videoUrl.split('/').pop();
        var trackingVideo = new CustomEvent('tracking-play-video');
        trackingVideo.videoSrc = videoUrl;
        trackingVideo.posterTitle = videoTitle ? videoTitle : fileName;
        window.dispatchEvent(trackingVideo);
    }

    function videoPauseTrack(event, videoTitle) {
        var _this = event;
        var videoUrl = _this.currentSrc();
        var fileName = videoUrl.split('/').pop();
        var videoDuration = _this.duration() ? _this.duration() : 0;
        var trackingVideo = new CustomEvent('tracking-over-video');
        trackingVideo.videoSrc = videoUrl;
        trackingVideo.videoDuration = videoDuration;
        trackingVideo.posterTitle = videoTitle ? videoTitle : fileName;
        window.dispatchEvent(trackingVideo);
    }

    /**
     * 生成视频弹窗
     * @param videoSrc 视频地址
     * @param videoType 视频类型
     */
    function generatorVideoDialog(videoSrc, videoType, videoTitle) {
        if (videoType === 'youtube' && window.TclConsent && !window.TclConsent.allowPlugin('youtube')) {
            window.TclConsent.openExternal(videoSrc);
            return;
        }
        var videoDialog = $('<div class="video-dialog"></div>');
        var videoWrapper = $('<div class="video-dialog-wrapper"></div>');
        var video = $('<video class="video-js tcl-player" preload="auto" webkit-playsinline="true" playsinline="true"></video>');
        var closeButton = $('<button class="close"><i class="tcl-icon icon-Linear_close"></i></button>');
        var videoTypes = {
            normal: 'video/mp4',
            hls: 'application/x-mpegURL',
            youtube: 'video/youtube',
        };
        videoWrapper.append(video);
        closeButton.on('click', function () {
            videoDialog.remove();
            stopBodyScroll(false);
        });
        videoWrapper.append(closeButton);
        videoDialog.append(videoWrapper);
        $('body').append(videoDialog);
        if (videoType === 'youtube') {
            videoDialog.addClass('youtube');
            if (window.screenInfo.scope === 'mobile') {
                var top = -1 * window.innerHeight / 2 + videoWrapper.height() / 2;
                closeButton.css("top", top);
            }
        }

        // active video
        var videoOnload = videojs(video.get(0), {
            sources: [{
                src: videoSrc,
                type: videoTypes[videoType]
            }],
            controls: videoType !== 'youtube',
            controlBar: {
                children: ["playToggle", "CurrentTimeDisplay", "TimeDivider", "DurationDisplay", "CustomControlSpacer", "VolumePanel", "RotateToggle", "FullscreenToggle", "ProgressControl"]
            },
            youtube: {ytControls: 1},
            plugins: {
                tclPlayer: {
                    autoplay: videoType === 'youtube' ? true : false,
                    type: videoType,
                }
            }
        });
        if (videoType !== 'youtube') {
            videoOnload.on('canplay', function () {
                videoOnload.play();
            })

        }
        videoOnload.on("playing", function(){videoPlayTrack(videoOnload, videoTitle)});
        videoOnload.on("pause", function(){videoPauseTrack(videoOnload, videoTitle)});
        stopBodyScroll(true);
    }

    /**
     * 初始化Swiper
     * @param el 挂载点
     * @param index Swiper编号
     */
    function createMessageCarousels(el, index) {
        // Get Container, Wrapper, Slides
        var container = $(el).find('.swiper');
        var wrapper = $(el).find('.swiper-wrapper');
        var slides = $(el).find('.swiper-slide');
        var columns = container.data('columns');
        // Tag element
        container.addClass('message-carousel-swiper' + index).data('index', index);
        // Check the children length
        if (slides.length <= 1) {
            wrapper.addClass('no-swiper');
            return;
        }
        // Get config of Slides
        var breakpoints = getBreakpointsByColumns(columns);
        new Swiper('.message-carousel-swiper' + index, {
            slidesPerView: 'auto',
            spaceBetween: 16,
            threshold: 10,
            breakpoints: breakpoints,
            navigation: {
                nextEl: '.message-carousel-swiper' + index + ' .swiper-button-next',
                prevEl: '.message-carousel-swiper' + index + ' .swiper-button-prev',
            },
            on: {
                imagesReady: function () {
                    syncHeightOfCards(el);
                },
                init: function (swiper) {
                    if (!$(swiper.$el).find('img').length) {
                        syncHeightOfCards(el);
                    }
                },
                slideChange: function(swiper) {
                    var activeIndex = swiper.activeIndex;
                    var total = swiper.slides.length;
                    var next = columns * Math.ceil((activeIndex + 1) / columns);
                    if(total > columns * 2 && total > next) {
                      for(var i = 0; i < columns; i++) {
                        var targetIndex = next + i;
                        if(targetIndex < total) {
                          var img = $(swiper.slides[targetIndex]).find('.message-card-item .thumbnail .background img');
                          img.removeAttr("data-lazy-ignore");
                          window.loadImg(img.get(0));
                        }
                      }
                    }
                },
            },
        });
        setRtlCardsDefaulAlign(el);
    }

    /**
     * 打开视频弹窗
     * @param el 当前组件El
     */
    function openVideoDialog(el) {
        var thumbnail = $(el).find('.message-card-item .thumbnail');
        thumbnail.off('click');
        thumbnail.on('click', function () {
            var useVideo = $(this).data('use-video');
            if (useVideo) return;
        });
        var playIcon = thumbnail.find('.icon-play');
        playIcon.off('click');
        playIcon.on('click', function () {
            var useVideo = $(this).parent().data('use-video');
            var videoType = $(this).parent().data('video-type');
            var videoSrc = $(this).parent().data('video-src');
            var videoTitle = $(this).parent().data('video-title');
            if (useVideo) {
                generatorVideoDialog(videoSrc, videoType, videoTitle);
            }
        });
    }

    function getDirection(x, y) {
        if (x > y) {
            return 'horizontal';
        }
        if (y > x) {
            return 'vertical';
        }
        return '';
    }

    function useTouch() {
        var startX = 0;
        var startY = 0;
        var deltaX = 0;
        var deltaY = 0;
        var offsetX = 0;
        var offsetY = 0;
        var direction = '';

        var isVertical = function () {
            return direction === 'vertical';
        };
        var isHorizontal = function () {
            return direction === 'horizontal';
        };

        var reset = function () {
            deltaX = 0;
            deltaY = 0;
            offsetX = 0;
            offsetY = 0;
            direction = '';
        };

        var start = function (event) {
            reset();
            startX = event.originalEvent.touches[0].clientX;
            startY = event.originalEvent.touches[0].clientY;
        };

        var move = function (event) {
            var touch = event.originalEvent.touches[0];
            // safari back will set clientX to negative number
            deltaX = touch.clientX < 0 ? 0 : touch.clientX - startX;
            deltaY = touch.clientY - startY;
            offsetX = Math.abs(deltaX);
            offsetY = Math.abs(deltaY);

            // lock direction when distance is greater than a certain value
            var LOCK_DIRECTION_DISTANCE = 10;
            if (!direction || (offsetX < LOCK_DIRECTION_DISTANCE && offsetY < LOCK_DIRECTION_DISTANCE)) {
                direction = getDirection(offsetX, offsetY);
            }
        };

        return {
            move: move,
            start: start,
            reset: reset,
            getClient: function () {
                return {
                    startX: startX,
                    startY: startY,
                    deltaX: deltaX,
                    deltaY: deltaY,
                    offsetX: offsetX,
                    offsetY: offsetY,
                    direction: direction,
                };
            },
            isVertical: isVertical,
            isHorizontal: isHorizontal,
        };
    }

    var DEFAULT_DURATION = 200;

    var count = 0;
    var offset = 0;
    var startOffset = 97;

    function getElementTranslateY(element) {
        var transform = window.getComputedStyle(element).transform;
        var translateY = transform.slice(7, transform.length - 1).split(', ')[5];
        return Number(translateY);
    }

    function clamp(num, min, max) {
        return Math.min(Math.max(num, min), max);
    }

    function getIndexByOffset(offset) {
        return clamp(Math.round(-offset / 40), 0, count - 1);
    }

    function setIndex(wrapper, index) {
        offset = -index * 40 + 97;

        wrapper.css({
            transform: 'translate3d(0, ' + offset + 'px, 0)',
            transitionDuration: DEFAULT_DURATION + 'ms',
            transitionProperty: 'all',
        });

        var selectedColumn = $(wrapper.find('.column__item').get(index));
        selectedColumn.addClass('selected').siblings().removeClass('selected');
    }

    var bodyEl = document.body;
    var top = 0;

    function stopBodyScroll(isFixed) {
        if (isFixed) {
            top = window.scrollY;

            bodyEl.style.position = 'fixed';
            bodyEl.style.top = -top + 'px';
            bodyEl.style.width = "100%";
        } else {
            bodyEl.style.position = '';
            bodyEl.style.top = '';
            bodyEl.style.width = '';

            window.scrollTo(0, top); // 回到原先的top
        }
    }

