(function () {
	var screenWidth = window.innerWidth;
	var isDesktop = window.screenInfo.scope === 'desktop';
	var featureMarquee = $('.featureMarquee-content');
	if (!featureMarquee.length) return;

	function init() {
		var listArr = featureMarquee.find('.featureMarquee-list');
		_.forEach(listArr, function (item, index) {
			
			var listContainer = $(item).find('.featureMarquee-list__container');
			var listWidth = listContainer.width();
			var speed = $(item).data('speed') || 'normal';
			var direction = $(item).data('direction');
			
			fillImageList(listContainer, listWidth);
			cloneList(item, listContainer);
			setAnimation(item, listWidth, speed, direction);

			if (isDesktop) {
				$(item).on('mouseenter', function () {
					$(this).addClass('featureMarquee-list--hover');
				});
				$(item).on('mouseleave', function () {
					$(this).removeClass('featureMarquee-list--hover');
				});
			}
		});
	}

	/**
	 * 填充图片到可以无缝滚动
	 */
	function fillImageList(listContainer, listWidth) {
		var htmlStr = listContainer.html();
		var fillNum = Math.ceil(screenWidth / listWidth);

		var result = new Array(fillNum * 2).fill(htmlStr);
		listContainer.html(result);
	}

	function cloneList(listItem, listContainer) {
		var cloneContainer = listContainer.clone(true);
		$(listItem).append(cloneContainer);
	}

	/**
	 * 设置轮播动画
	 */
	function setAnimation(listItem, listWidth, speed, direction) {
		var speedMap = {
			fast: 1000 / 60,
			normal: 1000 / 40,
			slow: 1000 / 20,
		};
		var transformWidth = direction === 'left' ? 0 : -listWidth;

		setInterval(function () {
			if ($(listItem).hasClass('featureMarquee-list--hover')) return;

			if (direction === 'left') {
				$(listItem).css({
					'will-change': 'transform',
					transform: 'translateX(-' + transformWidth++ + 'px)',
				});
				if (listWidth - transformWidth < 1) {
					transformWidth = 0;
				}
			} else {
				$(listItem).css({
					'will-change': 'transform',
					transform: 'translateX(' + transformWidth++ + 'px)',
				});
				if (transformWidth >= 0) {
					transformWidth = -listWidth;
				}
			}
		}, speedMap[speed]);
	}

	init();
})();

;
function setSwiper(){
	var imgBox = $('.feature-timeline-swiper-container');
	_.forEach(imgBox, function(el){
		if($(el).find('.image-box').length <= 1){
			$(el).find('.swiper-button-container').hide();
		}
		var simpleSwiper = null;
		var swiperWrapper = $(el).find('.swiper-wrapper');
		var swiperSlides = $(el).find('.swiper-slide');
		swiperSlides.length > 1 ?
			(simpleSwiper = new Swiper(el, {
				loop: true,
				effect: 'fade',
				threshold: 10,
				fadeEffect: {
					crossFade: true,
				},
			}))
			: swiperWrapper.addClass('no-swiper');
		$(el).find('.button-next').on('click', function () {
			var _this = this;
			$(this).addClass('click');
			simpleSwiper && simpleSwiper.slideNext();
			var nextTimer = setTimeout(function () {
				$(_this).removeClass('click');
				nextTimer&&clearTimeout(nextTimer);
			}, 300);
		});
		$(el).find('.button-prev').on('click', function () {
			var _this = this;
			$(this).addClass('click');
			simpleSwiper && simpleSwiper.slidePrev();
			var preTimer=setTimeout(function () {
				$(_this).removeClass('click');
				preTimer&&clearTimeout(preTimer);
			}, 300);
		});
	});
}


function fadeIn(){
	var timelineContainer = $('.timeline-container');
	_.forEach(timelineContainer,function(item){
		var Animate = Number($(item).find("#Animate").val());
		var pointLi = $(item).find('.timeline-box .item-wrap:not(:hidden)');
		if(Animate && pointLi.length){
			_.forEach(pointLi,function(item, index){
				var wh = $(window).height();
				var itop = item.getBoundingClientRect().top;
				if ( ((wh*0.85) - itop) > 0) {
					$(item).addClass('fadeInupoutShow');
				}else{
					$(item).removeClass('fadeInupoutShow');
				}
			});
		}
	});
}

(function () {
	var timelineContainer = $('.timeline-container');
	// 走马灯 start
	setSwiper();

	_.forEach(timelineContainer,function(item){
		var Amount = Number($(item).find("#Amount").val()) || 'all';
		var Animate = Number($(item).find("#Animate").val());
		var itemList = $(item).find('.timeline-box');
		_.forEach(itemList,function(el){
			if($(el).find(".item-wrap").length <= Amount || Amount == 'all'){
				$(el).find('.view-more .button').hide();
			}
			var leftBox = $(el).find('.left-box .item-wrap');
			var rightBox = $(el).find('.right-box .item-wrap');
			_.forEach(leftBox,function(i,index){
				if(Animate){
					$(i).addClass('fadeInupoutHide');
				}
			});
			_.forEach(rightBox,function(i,index){
				if(Animate){
					$(i).addClass('fadeInupoutHide');
				}
			});
			
			$(el).find('.view-more .button').click(function(){
				$(this).fadeOut();
				$(item).find('.item-wrap').show();
				fadeIn();
				window.lazyLoadImg();
			});

		});
	});

	setTimeout(function(){
		fadeIn();
	},1000);
	
	window.eventStack && window.eventStack.directive(EVENT_TYPES.SCROLL, 'feature-timeline-item-scroll', function(){
		fadeIn();
	});
	
})();

(function () {
  var subnavComp = $('.subnav-menus-container');
  if (subnavComp.length === 0) return;
  var menusAnchor = $('.subnav-menus-anchors');
  if (menusAnchor.length === 0) return;

  var rtl = $('html').hasClass('rtl');
  var leftArrow = $('.subnav-menus-anchors .subnav-menus-arrow-before');
  var rightArrow = $('.subnav-menus-anchors .subnav-menus-arrow-after');
  var menusWrapper = $('.subnav-menus-anchors .subnav-menus-items');
  var menusItems = $('.subnav-menus-anchors .subnav-menus-point');
  var logo = $(".subnav-menus-anchors .subnav-menus-logo img");
  var modulePanels = $('.subnav-container .subnav-module-panel');

  logo.one("load error", function() {
    setArrow();
  }).each(function() {
    if(this.complete) {
      $(this).load();
    }
  });

  // 屏幕大小变动
  $(window).on('resize', _.debounce(function () {
      setOffset();
      setArrow();
    }, 150)
  );

  // 菜单滚动
  menusWrapper.on('scroll', function() {
    setArrow();
  });

  leftArrow.click(function() {
    scrollToLeft();
  });

  rightArrow.click(function() {
    scrollToRight();
  });

  function setArrow() {
    var menusWrapperWidth = menusWrapper.width();
    var menusWrapperHeight = menusWrapper.height();
    var menusWrapperLeft = menusWrapper.position().left;
    var scrollLeft = menusWrapper.scrollLeft();
    var menusWidth = 0;
    menusItems.each(function() { 
      var rect = $(this).get(0).getBoundingClientRect();
      var width = rect ? rect.width : 0;
      menusWidth += width; 
    });
    menusWidth = Math.floor(menusWidth);
    if (menusWrapperWidth >= menusWidth) {
      leftArrow.hide();
      rightArrow.hide();
      return;
    }
    var showLeft = rtl ? scrollLeft < 0 : scrollLeft > 0;
    var showRight = rtl
      ? Math.floor(menusWidth + scrollLeft - menusWrapperWidth) > 0
      : Math.floor(menusWidth - scrollLeft - menusWrapperWidth) > 0;
    var showLeftArrow = rtl ? showRight : showLeft;
    var showRightArrow = rtl ? showLeft : showRight;
    showLeftArrow ? leftArrow.show() : leftArrow.hide();
    showRightArrow ? rightArrow.show() : rightArrow.hide();
    var leftArrowPos = menusWrapperLeft;
    var rightArrowPos = menusWrapperLeft + menusWrapperWidth - 40;
    leftArrow.css('left', leftArrowPos + 'px');
    rightArrow.css('left', rightArrowPos + 'px');
    leftArrow.css('height', menusWrapperHeight + 'px');
    rightArrow.css('height', menusWrapperHeight + 'px');
  }

  function scrollToLeft() {
    var menusWrapperWidth = menusWrapper.width();
    var scrollLeft = menusWrapper.scrollLeft();
    menusWrapper.animate({
      scrollLeft: scrollLeft - menusWrapperWidth,
    },{
      duration: 300,
      queue: false,
    });
  }

  function scrollToRight() {
    var menusWrapperWidth = menusWrapper.width();
    var scrollLeft = menusWrapper.scrollLeft();
    menusWrapper.animate({
      scrollLeft: scrollLeft + menusWrapperWidth,
    },{
      duration: 300,
      queue: false,
    });
  }

  menusItems.find('a').click(function() {
    var item = $(this).parent().get(0);
    var type = item.dataset.type;
    if(type === 'link') return;
    var point = item.dataset.id;
    scrollTo(point);
  })

  function scrollTo(point) {
    var sticky = menusAnchor.hasClass('sticky') || menusAnchor.hasClass('custom');
    var top = menusAnchor.css('top').replace(/[^\d|^\.]/g, '');
    var height = menusAnchor.height();
    var paddingTop = sticky ? top * 1 + height : 0;
    $('html, body').animate({
      scrollTop: $('#' + point).offset().top - paddingTop + 2,
    },{
      duration: 300,
      queue: false,
    });
  }

  function observeElements() {
    function handleObserve() {
      modulePanels.each(function (index) {
        var current = modulePanels.length - index - 1;
        var module = modulePanels.get(current);
        var anchorRect = menusAnchor.get(0).getBoundingClientRect();
        var rect = module.getBoundingClientRect();
        if(rect.top < anchorRect.top + anchorRect.height || current === 0) {
          var currentPoint = menusItems.eq(module.dataset.index);
          currentPoint.addClass('active').siblings('li').removeClass('active');
          var currentHalf = currentPoint.get(0).offsetWidth / 2;
          if(!currentHalf) return false;
          var wrapperHalf = menusWrapper.width() / 2;
          var currentLeft = currentPoint.position().left - menusWrapper.position().left;
          var wrapperScrollLeft = menusWrapper.scrollLeft();
          var scrollLeft = wrapperScrollLeft + currentLeft + currentHalf - wrapperHalf;
          menusWrapper.animate({
            scrollLeft: scrollLeft,
          },{
            duration: 300,
            queue: false,
          });
          return false;
        }
      });
    }
    handleObserve();
    document.addEventListener("scroll", _.debounce(handleObserve,100) , false);
  }

  function setOffset() {
    var sticky = menusAnchor.hasClass('sticky');
    var custom = menusAnchor.hasClass('custom');
    var customId = $('#customId').val();
    var top = 0;
    if(sticky) top = $('.sticky-header').height() * 1;
    else if(custom && customId) top = $('#' + customId).height() * 1;
    menusAnchor.css('top', top);
  }

  setArrow();
  setOffset();
  var sticky = menusAnchor.hasClass('sticky') || menusAnchor.hasClass('custom');
  if(sticky) observeElements();

})();

$(function () {
    var featureImageAndText = $('.image-text-group');
    if (!featureImageAndText.length) return;
    var device = window.innerWidth < 835 ? 'mobile' : 'desktop';

    var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');
    var intersectionObserver = new IntersectionObserver(function(entries, observer) {
        entries.forEach(function(entry) {
            if(entry.isIntersecting && entry.intersectionRatio > 0) {
                var target = entry.target;
                if($(target).attr('data-view-track')){
                    var viewData = JSON.parse($(target).attr('data-view-track'));
                    trackingSiperSlide.viewTrackData = viewData;
                    window.dispatchEvent(trackingSiperSlide);
                    observer.unobserve(target);
                }
            }
        })
        
    });

    function getPosterType(mobile, property) {
      var normalPosterType = mobile ? property.mobPosterType : property.pcPosterType;
      var youtubePosterType = mobile ? property.mobYoutubePosterType : property.pcYoutubePosterType;
      var posterType = property.videoType === 'youtube' ? youtubePosterType : normalPosterType; // 视频封面的类型
      if(!posterType) posterType = 'image';
      if(posterType === 'video') {
        // video 统一为 clip（clip 播放模式）
        posterType = 'clip';
      }
      return posterType;
    }

    /**
     * 获取 Video 参数
     */
    function getVideoOptions(videoEl) {
        var property = videoEl.dataset;
        /***
         *
         * true:视频不支持当前播放
         *
         * false:视频支持当前播放
         */
        var videoSource = device==='mobile' ? property.mobVideoSource : property.pcVideoSource;
        var src = property.videoType === 'youtube' ? property.videoSource : videoSource;
        var type = property.videoType === 'youtube' ? 'video/youtube' : property.videoFormat;
        var mode = (property.videoType === 'youtube'? property.videoMode: (device==='mobile'? (property.mobVideoMode === 'autoplay'? 'default': property.mobVideoMode): (property.pcVideoMode === 'autoplay'? 'default': property.pcVideoMode)));

        var controls = property.videoType !== 'youtube';
        var youtubePosterSource = device==='mobile' ? property.mobYoutubeVideoPoster : property.pcYoutubeVideoPoster;
        var normalPosterSource = device==='mobile' ? property.mobVideoPoster : property.pcVideoPoster;
        var posterSource = property.videoType === 'youtube' ? youtubePosterSource : normalPosterSource;  //image poster
        var autoPlayVideo = (device === 'mobile' ? property.mobVideoMode : property.pcVideoMode) === 'autoplay' && property.videoType !== 'youtube';
        var posterType = getPosterType(device === 'mobile', property);
        var options = {
            sources: [
                {
                    src: src,
                    type: type,
                },
            ],
            controls: controls,
            // fluid: true,
            controlBar: {
                children: [
                    'playToggle',
                    'CurrentTimeDisplay',
                    'TimeDivider',
                    'DurationDisplay',
                    'CustomControlSpacer',
                    'VolumePanel',
                    'RotateToggle',
                    'FullscreenToggle',
                    'ProgressControl',
                ],
            },
            youtube: {ytControls: 1},
            plugins: {
                tclPlayer: {
                    type: property.videoType,
                    mode: mode === 'default' ? '' : mode,
                    autoplay: autoPlayVideo,
                    cover: {
                        title: '',
                        subtitle: '',
                        button: '',
                        textAlign: '',
                        justifyContent: 'center',
                        alignItems: 'center',
                        theme: '',
                        poster: {
                            type: posterType,
                            image: posterSource,
                            alt: property.videoAlt,
                            video: posterSource
                        },
                    },
                },
            },
        };
        return options;
    }

    /**
     * 初始化视频
     */
    function initVideo(mediaItem, index) {
      var isInactive = index > 0;
      var videoEl = mediaItem.find('video.video-js').get(0);
      if(!videoEl) return;
      var options = getVideoOptions(videoEl);
      if (videoEl.dataset && videoEl.dataset.videoType === 'youtube' && window.TclConsent && !window.TclConsent.allowPlugin('youtube')) {
        window.TclConsent.applyYoutubeFallback(options, videoEl.dataset.videoSource);
      }
      var videojs = window.videojs(videoEl, options);
      videojs.on('init', function() {
        if(isInactive) this.setInactive();
        mediaItem.removeClass('lazy_load_video_wrap');
        mediaItem.siblings('style').remove();
        mediaItem.siblings('picture').remove();
      });
      var bigButtonClick = $(videojs.el()).find('.vjs-cover-content');
      bigButtonClick.click(function() {
        var viewTrackData = videojs["options_"]["data-click-video"];
        if(viewTrackData) {
          trackingSiperSlide.viewTrackData = JSON.parse(viewTrackData);
          window.dispatchEvent(trackingSiperSlide);
        }
      });
    }
    
    /**
     *
     * @param swiper
     * @param current
     * @param total
     * @returns {string}
     */
    function renderCustomPagination(swiper) {
        var pagination = $(swiper.$el).find('.swiper-pagination');
        $(pagination)
            .off('click', '.pagination-left')
            .on('click', '.pagination-left', function () {
                if (!swiper.autoplay.running) {
                    swiper.autoplay.start();
                }
                if (swiper.isBeginning) swiper.slideTo(swiper.slides.length - 1);
                else swiper.slidePrev();
            });
        $(pagination)
            .off('click', '.pagination-right')
            .on('click', '.pagination-right', function () {
                if (!swiper.autoplay.running) {
                    swiper.autoplay.start();
                }
                if (swiper.isEnd) swiper.slideTo(0);
                else swiper.slideNext();
            });
        return '<div class="pagination-left"></div><div class="pagination-right"></div>';
    }

    function getMediaBoxMaxOptions(mediasElem){
        var mediaParam = {width:0,height:0};
        mediasElem.each(function () {
            var currentW = $(this).outerWidth(true);
            var currentH = $(this).find('.image-group__item').outerHeight(true);
            if(currentH>mediaParam.height){
                mediaParam.width = currentW;
                mediaParam.height = currentH;
            }
        });
        return mediaParam;
    }

    function getMarketBoxMaxOptions(marketsElem){
        var marketParam = {width: 0, height: 0};
        marketsElem.each(function () {
            var textWrapHeight = $(this).find('.text-group__item__wrap').outerHeight(true);
            var currentW = $(this).outerWidth(true);
            var currentHeight = textWrapHeight ? textWrapHeight + 48 : 0;
            if(currentHeight > marketParam.height){
                marketParam.width = currentW;
                marketParam.height = currentHeight;
            }
        });
        return marketParam;
    }

    function getMaxBoxOptions(param){
        var mediaObj = getMediaBoxMaxOptions(param.media);
        var marketObj = getMarketBoxMaxOptions(param.market);
        if (mediaObj.height > marketObj.height) return mediaObj;
        return marketObj;
    }

    function getContentPad(elem, type, base) {
        var maxParma = type === 'market' ? getMarketBoxMaxOptions(elem) : type === 'media' ? getMediaBoxMaxOptions(elem) : getMaxBoxOptions(elem);
        var contentPad = (maxParma.height/(maxParma.width*base)) * 100;
        return contentPad;
    }
    
    //判断是否存在图片或者视频
    function isMediaHeight(target) {
        var isMedia = true;
        if (!target.length) {
            isMedia = false;
            return isMedia;
        }
        var imgList = target.find('img');
        var videoList = target.find('video')
        if (!imgList.length && !videoList.length) {
            isMedia = false;
            return isMedia;
        }
        return isMedia;
    }

    function setContentPad(params) {
        params.market && params.market.css('paddingTop', params.padTop * params.tbase + '%');
        params.media && 
        params.media.css('paddingTop', (params.mPadTop ? params.mPadTop : params.padTop) * params.mbase + '%') && 
        params.media.find('.image-group__item').css({'position': 'absolute', 'transform': 'translateY(-50%)'});
    }

    function setSwiperPagination(swiper,elem) {
        var textHeight=0;
        $.each(elem, function (index, textItem) {
            var _height=$(textItem).find(".text-group__item__wrap").height();
            if(_height){
                textHeight=_height;
            }
        });
        !textHeight&&swiper.find('.swiper-pagination').addClass('text-empty');
    }

    function initContentHeight(elem) {
        var swiper = $(elem).find('.swiper');
        var pcLayout = $(elem).attr('data-pc-layout');
        var carouselType = $(elem).attr('data-carousel-type');
        var courseItem = $(elem).attr('data-carousel-item');
        var contentType = $(elem).attr('data-content-type');
        var marketsElem = $(elem).find('.text-group__wrapper');
        var mediasElem = $(elem).find('.image-group__wrapper');
        var defElem = null;
        //判断是否存在图片或者视频
        var isMediaFlag = isMediaHeight(mediasElem);
        /**
         * 仅 pc左右布局单文模式，对图文高度进行对比，取最大高度
         */
        var marketAloneFlag=false;
        var marketsElemContent = marketsElem.find('.text-group__item__content');
        var options = {
            market: marketsElem,
            media: mediasElem,
            padTop: 0,
            tbase: 2,
            mbase: 1,
            mPadTop: 0,
            type:'market'
        };
        
        isMediaFlag?(options.type='media',defElem = mediasElem):(options.type='market',defElem = marketsElem);
        if (
            (device==='mobile' && contentType === 'carousel') ||
            (device==='desktop' && contentType === 'carousel' && !(pcLayout === 'row' || pcLayout === 'row-reverse'))
        ) {
            carouselType === 'alone'
                ? courseItem === 'marketing'
                ? ((options.media = null), (options.tbase = 1), (options.padTop = getContentPad(marketsElem, 'market', 1)))
                : ((options.market = null), (options.mbase = 1), (options.padTop = getContentPad(defElem, options.type, 1)))
                : ((options.tbase = 1),
                    (options.mbase = 1),
                    (options.padTop = getContentPad(marketsElem, 'market', 1)),
                    (options.mPadTop = getContentPad(defElem, options.type, 1)));
            setContentPad(options);
            swiper.length && setSwiperPagination(swiper,marketsElem);
            return;
        }

        if (device==='desktop' && (pcLayout === 'row' || pcLayout === 'row-reverse')) {
            if (contentType === 'carousel') {
                carouselType === 'alone'
                    ? courseItem === 'marketing'
                    ? ((options.tbase = 2), (options.mbase = 1))
                    : ((marketAloneFlag = true),(options.tbase = 1), (options.mbase = 2))
                    : ((options.tbase = 1), (options.mbase = 1));
                if(marketAloneFlag){
                    //单文 图片轮播模式盒子高度设置
                    options.padTop = getContentPad({market: marketsElem,media: mediasElem}, '', 2);
                    setContentPad(options);
                    return;
                }
                options.padTop = getContentPad(defElem, options.type, 2);
                setContentPad(options);
                marketsElemContent.css('overflow-y', 'auto');
                return;
            }
        }
    }

    /**
     * 发送自定义事件
     * @param {*} el
     */
    function sendCustomEvent(el) {
        var viewTrackData = $(el).data('viewTrack');
        trackingSiperSlide.viewTrackData = viewTrackData;
        window.dispatchEvent(trackingSiperSlide);
    }

    /**
     * swiper 初始化
     */
    function initSwiper(elem) {
        var swiperContainerTarget = $(elem).find('.swiper');
        var carouselDelay = $(elem).attr('data-carousel-delay');
        var delayTime = carouselDelay ? parseInt(carouselDelay) * 1000 : 0;
        var autoSetting =
            delayTime == 0
                ? false
                : {
                    delay: delayTime,
                    stopOnLastSlide: false,
                    disableOnInteraction: false,
                };
        var prevEl = swiperContainerTarget.find('.pagination-left');
        var nextEl = swiperContainerTarget.find('.pagination-right');
        var afterTrackingViewEle = [];
        var pagintaion = swiperContainerTarget.find('.swiper-pagination');
        var swiper = new Swiper(swiperContainerTarget.get(0), {
            autoplay: autoSetting, //可选选项，自动滑动
            // observer: true,
            // observeParents: true,
            preventClicks: true,
            touchStartPreventDefault: false, //为避免轮播与视频控件冲突，默认不阻止默认事件，在后面的监听中区分判断
            threshold: 10,
            loop: false,
            effect: 'fade',
            fadeEffect: {
                crossFade: true,
            },
            pagination: {
                el: pagintaion.get(0),
                clickable: true, //允许分页点击跳转
                // 自定义分页器
                type: 'custom',
                renderCustom: function (swiper) {
                    return renderCustomPagination(swiper);
                },
            },
            on: {
                slideChange: function(swiper) {
                    var activeIndex = swiper.activeIndex.toString();
                    if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
                        afterTrackingViewEle.push(activeIndex);
                        var dataViewTrackEle = $(swiper.slides[swiper.activeIndex]).find('[data-view-track]');
                        if (dataViewTrackEle.length > 0) {
                            dataViewTrackEle.each(function () {
                                sendCustomEvent(this);
                            })
                        }
                    }
                },
                slideChangeTransitionEnd: function(swiper) {
                  var activeItem = $(swiper.slides[swiper.activeIndex]).find('.image-group__item');
                  var previousItem = $(swiper.slides[swiper.previousIndex]).find('.image-group__item');
                  var activeVideo = activeItem.find('.video-js:not(video)');
                  if(!activeVideo.length) activeVideo = $('#' + activeItem.children().attr('cover-id')).find('.video-js:not(video)');;
                  var previousVideo = previousItem.find('.video-js:not(video)');
                  if(!previousVideo.length) previousVideo = $('#' + previousItem.children().attr('cover-id')).find('.video-js:not(video)');;
                  if(activeVideo.length) {
                    var player = activeVideo.get(0).player;
                    player.setActive && player.setActive();
                  }
                  if(previousVideo.length) {
                    var player = previousVideo.get(0).player;
                    player.setInactive && player.setInactive();
                  }
                },
                afterInit: function(swiper) {
                    var intersectionObserver = new IntersectionObserver(function(entries, observe) {
                        entries.forEach(function(entry) {
                            if (entry.isIntersecting && entry.intersectionRatio > 0) {
                                var target = entry.target;
                                if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
                                    var activeIndex = swiper.activeIndex.toString();
                                    afterTrackingViewEle.push(activeIndex);
                                    var otherViewTrackELe = $(swiper.$el).siblings().find('[data-view-track]');
                                    if(otherViewTrackELe.length > 0) {
                                        otherViewTrackELe.each(function() {
                                            sendCustomEvent(this);
                                        })
                                    }
                                    var dataViewTrackEle = $(swiper.slides[swiper.activeIndex]).find('[data-view-track]');
                                    if(dataViewTrackEle.length > 0) {
                                        dataViewTrackEle.each(function() {
                                            sendCustomEvent(this);
                                        })
                                    }
                                }
                                observe.unobserve(target);
                            }
                        });
                    });
                    intersectionObserver.observe(elem);
                },
                touchStart: function(swiper, event) {
                  var targetClass = event.target.className;
                  var videoCtlList = ['vjs-volume', 'vjs-progress', 'vjs-load-progress', 'vjs-play-progress', 'vjs-mouse-display'];
                  var isCtl = videoCtlList.some(function(str) {
                    return targetClass.indexOf(str) > -1;
                  });
                  // 视频控件上不允许拖动切换swiper，同时不阻止默认事件
                  if(isCtl) {
                      swiper.allowTouchMove = false;
                      return;
                  }
                  event.preventDefault();
                },
                touchEnd: function(swiper, event) {
                  // 松开时重置为全部允许拖动切换swiper
                  swiper.allowTouchMove = true;
                },
                click: function(swiper, event) {
                  // 由于全局阻止了默认点击，对于视频播放器，需要重新补上点击视频区域播放和暂停播放的逻辑
                  var target = event.target;
                  var isPlayer = target.nodeName === 'VIDEO' && target.className === 'vjs-tech' && target.currentTime > 0 && target.currentTime < target.duration;
                  if(isPlayer) {
                    if(target.paused) target.play();
                    else target.pause();
                  }
                },
            },
        });
        nextEl.on('click', function () {
            if (swiper.isEnd) swiper.slideTo(0);
            else swiper.slideNext();
        });
        prevEl.on('click', function () {
            if (swiper.isBeginning) swiper.slideTo(swiper.slides.length - 1);
            else swiper.slidePrev();
        });

        //非轮播模式
        if (!swiperContainerTarget.length) {
            var eleViewList = $(elem).find("[data-view-track]");
            if(eleViewList.length > 0) {
                eleViewList.each(function() {
                    var _this = this;
                    intersectionObserver.observe(_this);
                })
            }
            return;
        }
    }

    /**
     * 视频懒加载
     */
    function lazyLoadVideo(e) {
      var elem = e.data;
      if(!$(elem).parents('.image-text-group').length) return;
      var swiper = $(elem).parents('.image-text-group .swiper-wrapper');
      if(!swiper.length) {
        var mediaItem = $(elem).parent('.image-group__item');
        if(mediaItem && mediaItem.data('media-type') === 'video') initVideo(mediaItem, 0);
        return;
      }
      var mediaItems = swiper.find('.image-group__item');
      mediaItems.each(function(index) {
        if($(this).data('media-type') === 'video') {
          initVideo($(this), index);
        }
      });
    }

    function init() {
        featureImageAndText.each(function () {
            initSwiper(this);
            initContentHeight(this);
        });

        window.addEventListener('resize',_.debounce(function () {
            device = window.innerWidth < 835 ? 'mobile' : 'desktop';
            featureImageAndText.each(function () {
                initContentHeight(this);
            });
        }, 200));

        window.addEventListener('lazyload-video', lazyLoadVideo);
    }

    init();
});

(function () {
	var keyTabCarousels = $('.key-tab-carousel-container');
	if (keyTabCarousels.length == 0) {
		return;
	}
	var screenWidth = window.screenInfo.width;
	var deviceType = screenWidth > 834 ? 'desktop':screenWidth > 534 ? 'tablet':'mobile';
	var mediaSizeEnum={
		'desktop':2560,
		'tablet':834,
		'mobile':534,
	};
		var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');
	//编辑模式 ，使swiper纵向排列，便于组件添加
	var wcmmodeEdit = keyTabCarousels.eq(0).attr('data-swiper-wcmmode')==undefined ? true : false;
	/**
	 * 切换tab 根据当前激活的tab字体颜色设置tab整体内容颜色
	 * @param elem
	 * @param target
	 */
	function toggleTab(elem,target) {
		var color = target.attr('data-text-color');
		var headWrap = $(elem).find('.head-wrap');
		var tabWarpper=headWrap.find('.tab-warpper');
		var offsetX=target[0].offsetLeft - tabWarpper[0].clientWidth / 2+ target[0].clientWidth/ 2 ;
				tabWarpper.stop().animate({ scrollLeft: offsetX }, 300);
		headWrap.removeClass('text-white text-black');
		headWrap.addClass('text-'+color);
		target.addClass('active');
		$.each(target.siblings(), function (i, tabEl) {
			$(tabEl).removeClass('active');
		});
	}

	/**
	 * 切换tab内容可视区域事件绑定
	 * @param $elem
	 */
	function bindArrowTab($elem) {
		var tabWrapper = $elem.find('.tab-warpper');
		var preEl = $elem.find('.arrow-left');
		var nextEl = $elem.find('.arrow-right');
		var distanceX = deviceType === 'mobile' ? 183 :320;
		preEl.off('click').on('click',function () {
			tabWrapper.stop().animate({ scrollLeft: tabWrapper[0].scrollLeft - distanceX }, 300);
		});
		nextEl.off('click').on('click',function () {
			tabWrapper.stop().animate({ scrollLeft: tabWrapper[0].scrollLeft + distanceX }, 300);
		});
	}

	/**
	 * 判断是否有滚动条产生，初始化设置是否现实左右切换按钮
	 * @param elem
	 */
	function initArrowTab(elem) {
		var currentTabContainer = $(elem).find('.key-tab-carousel-tabs');
		var tabWrapper = currentTabContainer.find('.tab-warpper');
		if(!tabWrapper.length){return}
		//tabWrapper
		var scrollDistance = tabWrapper[0].scrollWidth - tabWrapper[0].clientWidth;
		var hasMirror = $('html').hasClass('rtl');
		if(tabWrapper.length&&(tabWrapper[0].scrollWidth>tabWrapper[0].clientWidth)){
			//产生滚动条
			tabWrapper.scroll(function() {
				var scrollLeft = this.scrollLeft;
				if(Math.abs(scrollLeft)<=10){
					//只能向右滚动
					hasMirror?(currentTabContainer.removeClass("has-r-arrow-tab"),currentTabContainer.addClass("has-l-arrow-tab")):(currentTabContainer.removeClass("has-l-arrow-tab"),currentTabContainer.addClass("has-r-arrow-tab"));
					currentTabContainer.removeClass("has-arrow-tab");
				}else if(Math.abs(scrollLeft) > 10 && Math.abs(scrollLeft) < scrollDistance-10){
					//左右均可滚动
					currentTabContainer.removeClass("has-l-arrow-tab");
					currentTabContainer.removeClass("has-r-arrow-tab");
					currentTabContainer.addClass("has-arrow-tab");
				}else{
					//只能向左滚动
					hasMirror?(currentTabContainer.addClass("has-r-arrow-tab"),currentTabContainer.removeClass("has-l-arrow-tab")):(currentTabContainer.addClass("has-l-arrow-tab"),currentTabContainer.removeClass("has-r-arrow-tab"));
					currentTabContainer.removeClass("has-arrow-tab");
				}
			});
			hasMirror?currentTabContainer.addClass("has-l-arrow-tab"):currentTabContainer.addClass("has-r-arrow-tab");
			bindArrowTab(currentTabContainer);
		}
	}

	/***
	 * 设置背景媒体高度
	 * @param mediaEl
	 * @param backgroundEl
	 * @param elem
	 * @param type image||video
	 */
	// function setBackgroundHeight(mediaEl,backgroundEl,elem,type) {
	// 	var container = $(elem).find('.key-tab-carousel-swiper');
	// 	var baseSize = mediaSizeEnum[deviceType];
	// 	var height,width;
	// 	type == 'image'?(height=mediaEl.height,width=mediaEl.width):(height=mediaEl.videoHeight,width=mediaEl.videoWidth);
	// 	var actualHeight = height*baseSize/width;
	// 	backgroundEl.css({height:actualHeight});
	// 	backgroundEl.parent('.background-box').css({height:actualHeight});
	// 	(type=='image')&&backgroundEl.css({backgroundSize:baseSize+'px'+' '+actualHeight+'px'});
	// 	container.css('min-height',actualHeight);
	// }

	/**
	 * 设置图片加载回调
	 * @param imageMedia
	 * @param elem
	 * @param callback
	 */
	// function initImageLoad(imageMedia,elem,callback) {
	// 	var imageSource = imageMedia.attr('data-image-source');
	// 	var image = new Image();
	// 	image.src = imageSource;
	// 	image.onload = function () {
	// 		callback && callback(image,imageMedia,elem,'image');
	// 	};
	// 	image.onerror = function () {
	// 		callback && callback(image,imageMedia,elem,'image');
	// 	};
	// }

	/**
	 * 设置视频加载回调
	 * @param videoMedia
	 * @param elem
	 * @param callback
	 */
	// function initVideoLoad(videoMedia,elem,callback) {
	// 	var videoEl = videoMedia.find('video');
	// 	if(videoEl[0].readyState==4){
	// 		callback && callback(videoEl[0],videoEl,elem,'video');
	// 		return;
	// 	}
	// 	videoEl[0].onloadeddata = function() {
	// 		callback && callback(this,videoEl,elem,'video');
	// 	};
	// 	videoEl[0].onerror = function() {
	// 		callback && callback(this,videoEl,elem,'video');
	// 	}
	// }

	/**
	 * 初始化设置背景多媒体加载
	 * @param elem
	 */
	// function initMediaLoad(elem) {
	// 	var imageMediaEl = $(elem).find('.key-tab-carousel-swiper .item-background.'+deviceType+'-image');
	// 	var videoMediaEl = $(elem).find('.key-tab-carousel-swiper .item-background.'+deviceType+'-video');
	// 	imageMediaEl.length&&initImageLoad(imageMediaEl,elem,setBackgroundHeight);
	// 	videoMediaEl.length&&initVideoLoad(videoMediaEl,elem,setBackgroundHeight);
	// }

	function isElementVisible(el) {
			var rect = el.getBoundingClientRect()
			var vWidth = window.innerWidth || document.documentElement.clientWidth
			var vHeight = window.innerHeight || document.documentElement.clientHeight
			if (
					rect.right < 0 ||
					rect.bottom < 0 ||
					rect.left > vWidth ||
					rect.top > vHeight
			) {
					return false
			}
			return true
	}

	function isMobileEventTrack(elem) {
			var tabItems = $(elem).find('.tab-item');
			if(tabItems.length > 0) {
					tabItems.each(function() {
							var _this = this;
							if(_this.hasAttribute('data-click-mobile-track')){
									var mobileEventTrack = _this.getAttribute('data-click-mobile-track');
									_this.setAttribute('data-click-track', mobileEventTrack);
							}
					})
					
			}
			var swiperEle = $(elem).find('.swiper-slide');
			if(swiperEle.length > 0) {
					swiperEle.each(function() {
							var _this = this;
							if(_this.hasAttribute('data-view-mobile-track')){
									var mobileEventTrack = _this.getAttribute('data-view-mobile-track');
									_this.setAttribute('data-view-track', mobileEventTrack);
							}
					})
			}
	}

	/**
	 * 初始化swiper
	 * @param elem
	 */
	function initSwiper(elem){
		var swiperContainerTarget = $(elem).find('.key-tab-carousel-swiper-content');
		var carouselDelay = $(elem).attr('data-swiper-delay');
		var delayTime = carouselDelay ? parseInt(carouselDelay) * 1000 : 0;
		var currentTabContainer = $(elem).find('.key-tab-carousel-tabs');
		var currentTabItem=currentTabContainer.find('.tab-item');
				var afterTrackingViewEle = [];
		var autoSetting =
			delayTime == 0
				? false
				: {
					delay: delayTime,
					stopOnLastSlide: false,
					disableOnInteraction: false,
					pauseOnMouseEnter:true,
				};
		var swiper = new Swiper(swiperContainerTarget.get(0), {
			autoplay: autoSetting, //可选选项，自动滑动
			allowTouchMove: false,
			preventClicks: false,
			threshold: 10,
			loop: false,
			effect: 'fade',
			fadeEffect: {
				crossFade: true,
			},
			on: {
				slideChange: function () {
					var eventDom = currentTabItem.eq(this.activeIndex);
					if (eventDom.length) {
						toggleTab(elem,eventDom);
					}
					var realIndex = this.activeIndex;
					if(isElementVisible(this.el) && afterTrackingViewEle.indexOf(realIndex.toString()) <= -1) {
							afterTrackingViewEle.push(realIndex.toString());
							var viewTrackData = JSON.parse($(this.slides[this.activeIndex]).attr('data-view-track'));
							trackingSiperSlide.this = this.slides[realIndex];
							trackingSiperSlide.viewTrackData = viewTrackData;
							window.dispatchEvent(trackingSiperSlide);
					}
				},
				resize: function () {
					initArrowTab(elem);
					var currentScreenWidth = window.screenInfo.width;
					var currentDevice = currentScreenWidth > 834 ? 'desktop':currentScreenWidth > 534 ? 'tablet':'mobile';
					if(currentDevice === deviceType)return;
					deviceType = currentDevice;
					// initMediaLoad(elem);
				},			
				afterInit: function() {
						var keyTabCarouselViewTrack = $(elem).find('.key-tab-carousel-swiper');
						var intersectionObserver = new IntersectionObserver(function(entries) {
								entries.forEach(function(entry) {
										if (entry.isIntersecting && entry.intersectionRatio > 0) {
												var target = entry.target;
												var activeEle = $(target).find('.swiper-slide');
												var activeIndex = '0';
												if(activeEle.length > 1){
														activeEle = $(target).find('.swiper-slide-active');
														activeIndex = activeEle.attr('data-swiper-slide-index');
												}
												if(afterTrackingViewEle.indexOf(activeIndex) <= -1) {
														afterTrackingViewEle.push(activeIndex);
														var viewData = JSON.parse(activeEle.attr('data-view-track'));
														trackingSiperSlide.swiper = target;
														trackingSiperSlide.viewTrackData = viewData;
														window.dispatchEvent(trackingSiperSlide);
												}
										}
								});
						});
						intersectionObserver.observe(keyTabCarouselViewTrack[0]);
						if(screenWidth <= 834) {
								isMobileEventTrack(elem);
						}
				}
			},
		});

		/**
		 * tabItem事件绑定 设置仅绑定文字和图标
		 */
		currentTabItem.on('click','._target',function () {
			var parent=$(this).parent();
			var index = parent[0].dataset.index;
			swiper.slideTo(index, 1000, false);
			toggleTab(elem,parent);
		});

	}

	/**
	 * 组件初始化设置
	 */
	keyTabCarousels.each(function () {
		initArrowTab(this);
		// initMediaLoad(this);
		wcmmodeEdit&&initSwiper(this);
	});

})();

