(function($) {
    $(function() {
        // 创建media
        var _GSAPmatchMedia = gsap.matchMedia();

        var _animations = function(way) {
            way = way || 'pc';
            // 获取所有具有 data-scroll 属性的元素
            var allElements = document.querySelectorAll('[data-scroll]');

            // 执行相应的动画
            for (var i = 0; i < allElements.length; i++) {
                var element = allElements[i];
                var animationType = element.getAttribute('data-scroll'); // 执行动画方法名
                var animationModel = element.getAttribute('data-model'); // 执行模式

                if (animationType && typeof $[animationType] === 'function') {
                    if (animationModel === 'all' || animationModel === way) {
                        $[animationType]({ mobile: (way === 'mobile' ? true : false), el: element })
                    }
                }
            };
        };

        $.scrollBanners = [];
        var _clearArr = function(arr, cb) {
            if (arr.length > 0) {
                for (var i = 0; i < arr.length; i++) {
                    arr[i].kill();
                };

                $.scrollBanners = [];
            };

            typeof cb === 'function' && cb();

        };

        // ipad ~ pc >=768
        _GSAPmatchMedia.add('(min-width: 535px)', function() {
            _clearArr($.scrollBanners, function() {
                _animations('pc');
            });

            // 必须要有
            return function() {};
        });

        // mobile <768
        _GSAPmatchMedia.add('(max-width: 534px)', function() {
            _clearArr($.scrollBanners, function() {
                _animations('mobile');
            });

            // 必须要有
            return function() {};
        });
    })
})(jQuery);
$(function () {
    var dialogPopUp = $('.feature-dialog-container');
    if (!dialogPopUp.length) return;
    dialogPopUp.each(function () {
        $('body').append(this);
    });

    var openPopDialog = function (dialogId) {
        var matchingEle = $('body').find('#' + dialogId);
        if (matchingEle.length > 0) {
            var closeIcon = matchingEle.find('.close-icon');
            var dialogRichText = matchingEle.find('.dialog-rich-text');
            $('body').addClass('popup-dialog-body-style');
            matchingEle.addClass('is-open');
            setTimeout(function () {
                matchingEle.addClass('active');
            }, 0)
            closeIcon.off('click').on('click', function () {
                matchingEle.removeClass('active');
                $('body').removeClass('popup-dialog-body-style');
                setTimeout(function () {
                    dialogRichText.scrollTop(0);
                    matchingEle.removeClass('is-open');
                }, 400)
            })
        }
    }
    window.openPopDialog = openPopDialog;
});
